<script setup lang="ts">import{computed,onMounted,reactive,ref,watch}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import http from'../../api/http';import TablePager from'../../shared/components/TablePager.vue';const props=defineProps<{kind:string}>();const cfg:any={leads:{title:'销售线索',api:'/crm/leads'},opportunities:{title:'商机管理',api:'/crm/opportunities'},quotations:{title:'报价管理',api:'/crm/quotations'},contracts:{title:'合同管理',api:'/crm/contracts'},forecast:{title:'销售预测',api:'/crm/forecast'},complaints:{title:'客诉协同',api:'/crm/complaints'}};const c=computed(()=>cfg[props.kind]),rows=ref<any[]>([]),page=ref(1),size=ref(20),total=ref(0),keyword=ref(''),status=ref(''),loading=ref(false),dialog=ref(false),form=reactive<any>({});const fields=computed(()=>({leads:[['leadNo','线索编号'],['customerName','客户名称'],['contactName','联系人'],['contactPhone','联系电话'],['sourceChannel','来源渠道']],opportunities:[['opportunityNo','商机编号'],['opportunityName','商机名称'],['customerCode','客户编码'],['expectAmount','预计金额']],quotations:[['quotationNo','报价编号'],['opportunityNo','商机编号'],['customerCode','客户编码'],['validUntil','有效期']],contracts:[['contractNo','合同编号'],['contractName','合同名称'],['quotationId','报价记录编号'],['effectiveDate','生效日期'],['expireDate','截止日期']],complaints:[['complaintNo','客诉编号'],['customerCode','客户编码'],['salesOrderNo','销售订单'],['productCode','产品编码'],['severity','严重程度'],['problemDesc','问题描述']]}as any)[props.kind]||[]);async function load(){loading.value=true;try{const{data}=await http.get(c.value.api,{params:{page:page.value,size:size.value,keyword:keyword.value||undefined,status:status.value||undefined}});rows.value=data.data.content;total.value=data.data.totalElements}finally{loading.value=false}}function create(){Object.keys(form).forEach(k=>delete form[k]);if(props.kind==='quotations')Object.assign(form,{currency:'CNY',taxRate:13,lines:[{lineNo:1,productCode:'',productName:'',qty:1,unitCode:'PCS',standardPrice:0,salesPrice:0,standardCost:0}]});if(props.kind==='contracts')form.paymentPlans=[{periodNo:1,dueDate:'',planRatio:100,planAmount:0}];dialog.value=true}async function save(){await http.post(c.value.api,form);ElMessage.success('保存成功');dialog.value=false;page.value=1;await load()}async function promptAction(row:any,action:string,label:string){try{const{value}=await ElMessageBox.prompt(`请输入${label}所需信息`,label,{inputValue:''});let body:any={reason:value};if(action==='assign')body={username:value,reason:'业务分配'};if(action==='follow')body={followType:'CALL',content:value};if(action==='convert')body={customerCode:value,opportunityName:`${row.customer_name}商机`};if(action==='stage'){const parts=value.split('|');body={code:parts[0].trim().toUpperCase(),reason:parts.slice(1).join('|').trim()}};await http.post(`${c.value.api}/${row.id}/${action}`,body);ElMessage.success(`${label}成功`);await load()}catch(e:any){if(e!=='cancel')ElMessage.error(e.message||`${label}失败`)}}async function direct(row:any,action:string,label:string){try{await http.post(`${c.value.api}/${row.id}/${action}`);ElMessage.success(`${label}成功`);await load()}catch(e:any){ElMessage.error(e.message||`${label}失败`)}}watch(()=>props.kind,()=>{page.value=1;load()});onMounted(load)</script>
<template><section class="page"><div class="head"><div><span>客户关系业务</span><h1>{{c.title}}</h1><p>真实业务单据、状态流转、审批与上下游来源追踪。</p></div><el-button v-if="kind!=='forecast'" type="primary" @click="create">新增{{c.title}}</el-button></div><el-card shadow="never"><div class="bar"><el-input v-model="keyword" placeholder="输入编号、客户或名称" clearable/><el-select v-model="status" clearable placeholder="全部状态"><el-option v-for="s in ['NEW','FOLLOWING','CONVERTED','DRAFT','PENDING','APPROVED','ACTIVE','CLOSED']" :key="s" :label="$zh(s)" :value="s"/></el-select><el-button @click="page=1;load()">查询</el-button></div><el-table :data="rows" v-loading="loading" stripe><el-table-column v-for="k in Object.keys(rows[0]||{}).slice(0,8)" :key="k" :label="$zhKey(k)" min-width="125" show-overflow-tooltip><template #default="{row}">{{$zh(row[k])}}</template></el-table-column><el-table-column label="操作" width="280" fixed="right"><template #default="{row}"><template v-if="kind==='leads'"><el-button link @click="promptAction(row,'assign','分配')">分配</el-button><el-button link @click="promptAction(row,'follow','跟进')">跟进</el-button><el-button link type="primary" @click="promptAction(row,'convert','转商机')">转商机</el-button></template><template v-if="kind==='quotations'"><el-button link @click="direct(row,'new-version','升版')">升版</el-button><el-button link type="primary" @click="direct(row,'submit','提交审批')">提交审批</el-button><el-button link type="success" @click="direct(row,'activate','报价生效')">生效</el-button></template><template v-if="kind==='contracts'"><el-button link @click="direct(row,'submit','提交审批')">提交审批</el-button><el-button link @click="direct(row,'activate','生效')">生效</el-button><el-button link @click="promptAction(row,'new-version','合同变更升版')">变更升版</el-button><el-button link type="primary" @click="direct(row,'create-order','生成订单')">生成订单</el-button></template><template v-if="kind==='opportunities'"><el-button link @click="promptAction(row,'stage','推进阶段')">推进阶段</el-button></template></template></el-table-column></el-table><TablePager v-model:page="page" v-model:size="size" :total="total" @change="load"/></el-card><el-dialog v-model="dialog" :title="`新增${c.title}`" width="760px"><el-form label-position="top"><el-row :gutter="16"><el-col v-for="f in fields" :key="f[0]" :span="12"><el-form-item :label="f[1]"><el-input v-model="form[f[0]]"/></el-form-item></el-col></el-row><template v-if="kind==='quotations'"><h4>报价明细</h4><el-table :data="form.lines" border><el-table-column label="产品编码"><template #default="{row}"><el-input v-model="row.productCode"/></template></el-table-column><el-table-column label="数量"><template #default="{row}"><el-input-number v-model="row.qty"/></template></el-table-column><el-table-column label="标准价"><template #default="{row}"><el-input-number v-model="row.standardPrice"/></template></el-table-column><el-table-column label="销售价"><template #default="{row}"><el-input-number v-model="row.salesPrice"/></template></el-table-column><el-table-column label="标准成本"><template #default="{row}"><el-input-number v-model="row.standardCost"/></template></el-table-column></el-table></template><template v-if="kind==='contracts'"><h4>回款计划</h4><el-form-item label="计划到期日"><el-date-picker v-model="form.paymentPlans[0].dueDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="计划比例（%）"><el-input-number v-model="form.paymentPlans[0].planRatio" :min="0" :max="100"/></el-form-item><el-form-item label="计划金额"><el-input-number v-model="form.paymentPlans[0].planAmount" :min="0"/></el-form-item></template></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></section></template>
<style scoped>.page{max-width:1500px;margin:auto}.head{display:flex;align-items:end;justify-content:space-between;margin-bottom:16px}.head span{font-size:11px;color:#3976d5}.head h1{margin:5px 0;color:#263f5c}.head p{font-size:12px;color:#8391a4}.bar{display:flex;gap:8px;margin-bottom:14px}.bar .el-input{width:280px}.bar .el-select{width:160px}</style>
